    /// Position in `ALL`; index into a `JitConfig` snapshot.
    /// `ALL` lists variants in declaration order in every profile,
    /// so the discriminant is the index even with cfg-gated variants.
    pub const fn index(self) -> usize {
        self as usize
    }

